import { Schema } from '@livestore/utils/effect'

import { EventSequenceNumber } from '../schema/mod.ts'

export class IsOfflineError extends Schema.TaggedError<IsOfflineError, { readonly brand: unique symbol }>(
  '~@livestore/common/IsOfflineError',
)('IsOfflineError', {
  cause: Schema.Defect(),
}) {}

/** Unique ID generated by the backend when its created. Used to check whether the backend identity has changed. */
export const BackendId = Schema.String.annotate({ title: '@livestore/sync-cf:BackendId' })

export class BackendIdMismatchError extends Schema.TaggedError<
  BackendIdMismatchError,
  { readonly brand: unique symbol }
>('~@livestore/common/BackendIdMismatchError')('BackendIdMismatchError', {
  expected: BackendId,
  received: BackendId,
}) {}

export class ServerAheadError extends Schema.TaggedError<ServerAheadError, { readonly brand: unique symbol }>(
  '~@livestore/common/ServerAheadError',
)('ServerAheadError', {
  minimumExpectedNum: EventSequenceNumber.Global.Schema,
  providedNum: EventSequenceNumber.Global.Schema,
}) {}
